turt: Turtle = Turtle()
turt.penup()
turt.speed(0)
wHeight = turt.screen.window_height()
wWidth = turt.screen.window_width()

class Toggle:
    def __init__(self):
        self.boolean = True

    def switch(self):
        self.boolean ^= 1

    def get(self):
        return self.boolean


sunYellow = Toggle()

def toggleSun(_, __):
    print(2)
    if sunYellow.get():
        sunYellow.switch() 
        turt.setpos(-wWidth//2, wHeight//2)
        turt.dot(100, "#ffff00")
    else:
        sunYellow.switch()
        turt.setpos(-wWidth//2, wHeight//2)
        turt.dot(100, "#ff0000")


# x and y of bottom left
def drawRect(xPos, yPos, w, h, color):
    prevColor = turt.fillcolor()
    prevPos = turt.pos()

    turt.setpos(xPos, yPos)
    turt.setheading(0)
    turt.fillcolor(color)

    turt.begin_fill()
    turt.forward(w)
    turt.left(90)
    turt.forward(h)
    turt.left(90)
    turt.forward(w)
    turt.left(90)
    turt.forward(h)
    turt.end_fill()

    turt.setpos(prevPos)    
    turt.fillcolor(prevColor)




